import{_ as e}from"./chunks/tableau.CZ_ooqZJ.js";import{_ as a,o as r,c as s,a2 as o}from"./chunks/framework.CQxpk36T.js";const m=JSON.parse('{"title":"The dashboard","description":"","frontmatter":{},"headers":[],"relativePath":"en/home-assistant/tableau.md","filePath":"en/home-assistant/tableau.md","lastUpdated":1793574169000}'),i={name:"en/home-assistant/tableau.md"};function d(n,t,h,l,g,c){return r(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="the-dashboard" tabindex="-1">The dashboard <a class="header-anchor" href="#the-dashboard" aria-label="Permalink to &quot;The dashboard&quot;">​</a></h1><p>The <strong>Tableau</strong> (dashboard) tab gives each device a tile made for it, with a small drawing that shows its state. Tiles are sorted <strong>by building, then by room</strong>, in the order of <code>propriete.ts</code>.</p><p><img src="'+e+'" alt="The example house&#39;s dashboard"></p><h2 id="tiles" tabindex="-1">Tiles <a class="header-anchor" href="#tiles" aria-label="Permalink to &quot;Tiles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Device</th><th>Tile</th><th>Tap</th><th>Details (long press)</th></tr></thead><tbody><tr><td>Light</td><td>Glowing lamp, brightness slider</td><td>On, off</td><td>Brightness, colour temperature</td></tr><tr><td>Switch, plug, fan</td><td>Arrêt / Marche (off / on)</td><td>Toggle</td><td></td></tr><tr><td>Roller shutter</td><td>Curtain coming down</td><td>▲ ■ ▼</td><td>Position</td></tr><tr><td>Garage door, gate</td><td>Door going up</td><td>Ouvrir / Fermer / Arrêter (open / close / stop)</td><td></td></tr><tr><td>Thermostat</td><td>Dial</td><td></td><td>Drag the handle or − / +, modes, presets</td></tr></tbody></table><p><strong>Sensors</strong> (temperature, humidity, power, openings) are shown as chips in their room&#39;s title.</p><h2 id="gestures" tabindex="-1">Gestures <a class="header-anchor" href="#gestures" aria-label="Permalink to &quot;Gestures&quot;">​</a></h2><ul><li><strong>Tap</strong> a tile to act on it.</li><li><strong>Drag</strong> a lamp&#39;s slider to set its brightness: the lamp follows while you drag, without waiting for you to let go.</li><li><strong>Long press</strong> (or right-click) opens the details: brightness, position, mode, and <strong>Épingler</strong> (pin) as a favourite.</li></ul><p>Until the device has answered a command, its drawing <strong>pulses</strong>.</p><h2 id="favourites-scenes-search" tabindex="-1">Favourites, scenes, search <a class="header-anchor" href="#favourites-scenes-search" aria-label="Permalink to &quot;Favourites, scenes, search&quot;">​</a></h2><ul><li><strong>Favourites</strong> come first on the dashboard.</li><li>Home Assistant <strong>scenes</strong> and <strong>scripts</strong> form a row of buttons.</li><li><strong>Search</strong> finds a device by its name, room or building, regardless of accents and case.</li></ul><h2 id="what-doesn-t-appear" tabindex="-1">What doesn&#39;t appear <a class="header-anchor" href="#what-doesn-t-appear" aria-label="Permalink to &quot;What doesn&#39;t appear&quot;">​</a></h2><p>Only devices <strong>assigned to an Area</strong> get a tile: Home Assistant often has hundreds. Configuration, diagnostic and hidden entities are left out. Areas without a room in <code>propriete.ts</code> (garden, terrace) are grouped under <strong>Extérieur</strong> (outside).</p>',13)])])}const b=a(i,[["render",d]]);export{m as __pageData,b as default};
